import React from 'react'
import './index.css'
import { BrowserRouter, Routes, Route } from 'react-router-dom'
import { ThemeProvider, CssBaseline } from '@mui/material'
import Navbar from './components/Navbar'
import { AccessibilityProvider, useAccessibility } from './context/AccessibilityContext'
import { buildAppTheme } from './theme'
import Landing from './pages/Landing'
import Cognitive from './pages/Cognitive'
import Hearing from './pages/Hearing'
import Visual from './pages/Visual'
import Mobility from './pages/Mobility'
import Speech from './pages/Speech'
import Neurodivergent from './pages/Neurodivergent'
import Showcase from './pages/Showcase'
import Login from './pages/Login'
import Signup from './pages/Signup'
import Learner from './pages/onboarding/Learner'
import Contributor from './pages/onboarding/Contributor'
import Mentor from './pages/onboarding/Mentor'
import Explore from './pages/onboarding/Explore'
import LearnerDashboard from './pages/LearnerDashboard'
import ContributorDashboard from './pages/ContributorDashboard'
import AdminDashboard from './pages/AdminDashboard'
import SubmitProblem from './pages/SubmitProblem'
import SubmitLanding from './pages/SubmitLanding'
import ContributorLanding from './pages/ContributorLanding'
import ProtectedRoute from './components/ProtectedRoute'

export default function App() {
  return (
    <AccessibilityProvider>
      <AppShell />
    </AccessibilityProvider>
  )
}

function AppShell() {
  const { dark, contrast, fontSize } = useAccessibility()
  const theme = React.useMemo(() => buildAppTheme({ dark, contrast, fontSize }), [dark, contrast, fontSize])

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
        <BrowserRouter>
      <Navbar />
        <main id="main" role="main">
        <Routes>
        <Route path="/" element={<Landing />} />
        <Route path="/cognitive" element={<Cognitive />} />
        <Route path="/hearing" element={<Hearing />} />
        <Route path="/visual" element={<Visual />} />
        <Route path="/mobility" element={<Mobility />} />
        <Route path="/speech" element={<Speech />} />
        <Route path="/neurodivergent" element={<Neurodivergent />} />
        <Route path="/showcase" element={<Showcase />} />
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<Signup />} />
          <Route path="/learner" element={
            <ProtectedRoute allowedRoles={["learner"]}>
              <LearnerDashboard />
            </ProtectedRoute>
          } />
          <Route path="/submit" element={<SubmitLanding />} />
          <Route path="/submit-problem" element={<ProtectedRoute allowedRoles={["learner"]}><SubmitProblem /></ProtectedRoute>} />
          <Route path="/contribute" element={<ContributorLanding />} />
          <Route path="/contributor" element={
            <ProtectedRoute allowedRoles={["contributor"]}>
              <ContributorDashboard />
            </ProtectedRoute>
          } />
          <Route path="/admin" element={
            <ProtectedRoute allowedRoles={["admin"]}>
              <AdminDashboard />
            </ProtectedRoute>
          } />
  <Route path="/onboarding/learner" element={<Learner />} />
  <Route path="/onboarding/contributor" element={<Contributor />} />
  <Route path="/onboarding/mentor" element={<Mentor />} />
  <Route path="/onboarding/explore" element={<Explore />} />
      </Routes>
      </main>
      </BrowserRouter>
    </ThemeProvider>
  )
}
